    $expr: { $lte: [{ $add: ["$refundedMinor", 1250] }, "$amountMinor"] } },   // the guard
  { $push: { refunds: { refundId: "ref-2", amountMinor: NumberLong(1250), at: new Date() } },
    $inc:  { refundedMinor: NumberLong(1250) } })                                // one document: atomic
// modifiedCount 1: applied. 0: not settled, or it would refund too much.

// w: 1          the primary has it. Cut off now: rolled back when it rejoins, client never told.
// w: "majority" 2 of 3 members have it. Cut off now: any new primary has it too. It survives.
